<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';$user=require_role('volunteer');
require_once __DIR__.'/../includes/volunteer_tasks.php';
$taskHistory=$taskHistory??false;$taskRecent=$taskRecent??false;
$title=$taskRecent?'Recent collection tasks':($taskHistory?'Completed task history':'My collection tasks');
$statuses=['all','assigned','accepted','collected','delivered','cancelled'];$status=$_GET['status']??'all';$search=$_GET['search']??'';
$receipt=$_GET['receipt']??'all';
if (!is_string($receipt) || !in_array($receipt,['all','awaiting','confirmed'],true)) {http_response_code(400);exit('Invalid receipt filter.');}
$page=filter_var($_GET['page']??'1',FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>1000000]]);
if (!is_string($status) || !in_array($status,$statuses,true) || !is_string($search) || !mb_check_encoding($search,'UTF-8') || mb_strlen($search)>150 || str_contains($search,"\0") || $page===false) {http_response_code(400);exit('Invalid task filters.');}
$search=trim($search);$where='t.volunteer_id=?';$params=[(int)$user['id']];
if ($taskHistory) {
    $where.=" AND t.status='delivered' AND t.delivered_at IS NOT NULL AND r.status='approved' AND d.status IN ('delivered','completed')";
    if ($receipt!=='all') {$where.=' AND d.status=?';$params[]=$receipt==='confirmed'?'completed':'delivered';}
}
if ($status!=='all') {$where.=' AND t.status=?';$params[]=$status;}
if ($search!=='') {$where.=" AND d.food_name LIKE ? ESCAPE '!'";$params[]='%'.str_replace(['!','%','_'],['!!','!%','!_'],$search).'%';}
try {
    $from=' FROM collection_tasks t JOIN donation_requests r ON r.id=t.request_id JOIN donations d ON d.id=r.donation_id JOIN organizations o ON o.id=r.organization_id';
    $query=db()->prepare("SELECT COUNT(*) $from WHERE $where");$query->execute($params);$total=(int)$query->fetchColumn();
    $limit=$taskRecent?5:20;$pages=$taskRecent?1:max(1,(int)ceil($total/$limit));$page=min($page,$pages);$offset=($page-1)*$limit;
    $query=db()->prepare("SELECT t.id,t.status AS task_status,t.delivered_at,d.food_name,d.status,d.deadline_at,o.organization_name,GREATEST(t.updated_at,d.updated_at) AS latest_update $from WHERE $where ORDER BY latest_update DESC,t.id DESC LIMIT $limit OFFSET $offset");$query->execute($params);$tasks=$query->fetchAll();
} catch (PDOException $exception) {error_log('Volunteer tasks failed. Code: '.$exception->getCode());donation_load_error();}
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title><?= e($title) ?> | <?= e(APP_NAME) ?></title><link rel="stylesheet" href="<?= e(app_url('assets/css/bootstrap.min.css')) ?>"><link rel="stylesheet" href="<?= e(app_url('assets/css/style.css')) ?>"></head><body>
<?php $navigationUser=$user;require __DIR__.'/../includes/header.php'; ?><main class="container py-5" id="main-content"><div class="row g-4"><?php $volunteerPage=$taskRecent?'recent':($taskHistory?'history':'tasks');require __DIR__.'/../includes/volunteer_sidebar.php'; ?>
<section class="col-lg-9" aria-labelledby="tasks-heading"><div class="dashboard-welcome mb-4"><h1 class="h2" id="tasks-heading"><?= e($title) ?></h1><p class="text-secondary"><?= $taskHistory?'Review completed deliveries and organization receipt confirmations.':'Review your assigned collections and pickup and delivery details.' ?></p></div>
<form method="get" class="account-card mb-4"><div class="row g-3"><div class="col-md-6"><label class="form-label" for="search">Food name</label><input class="form-control" id="search" name="search" maxlength="150" value="<?= e($search) ?>"></div><?php if ($taskHistory): ?><div class="col-md-4"><label class="form-label" for="receipt">Receipt status</label><select class="form-select" id="receipt" name="receipt"><?php foreach (['all'=>'All deliveries','awaiting'=>'Awaiting confirmation','confirmed'=>'Receipt confirmed'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $receipt===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><?php else: ?><div class="col-md-4"><label class="form-label" for="status">Task status</label><select class="form-select" id="status" name="status"><?php foreach ($statuses as $option): ?><option value="<?= e($option) ?>" <?= $status===$option?'selected':'' ?>><?= e(ucfirst($option)) ?></option><?php endforeach; ?></select></div><?php endif; ?><div class="col-md-2 d-flex align-items-end"><button class="btn btn-community">Filter</button></div></div></form>
<div class="dashboard-panel"><div class="dashboard-panel-heading"><h2>Collection tasks</h2><span><?= $taskRecent?'Latest 5 of ':'' ?><?= e((string)$total) ?> matching tasks</span></div><?php if (!$tasks): ?><div class="dashboard-empty"><h3>No matching collection tasks.</h3><p>An administrator assigns volunteers after a donor approves a request. Try another filter if you already have tasks.</p></div><?php else: ?><div class="table-responsive"><table class="table dashboard-table align-middle mb-0"><caption class="visually-hidden">Your assigned collections, with times in Sri Lanka time.</caption><thead><tr><th>Food</th><th>Organization</th><th>Task</th><th>Donation</th><th><?= $taskHistory?'Delivered at':'Collect by' ?></th><th>Details</th></tr></thead><tbody><?php foreach ($tasks as $task): ?><tr><td><?= e($task['food_name']) ?></td><td><?= e($task['organization_name']) ?></td><td><?= status_badge($task['task_status']) ?></td><td><?= status_badge(donation_display_status($task)) ?></td><td><?= e(dashboard_date($taskHistory?$task['delivered_at']:$task['deadline_at'])) ?></td><td><a class="home-link" href="<?= e(app_url('volunteer/task.php?id='.$task['id'])) ?>">View &rarr;</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<?php if ($pages>1): ?><nav class="donation-pagination mt-4" aria-label="Task pages"><?php if ($page>1): ?><a class="btn btn-quiet" href="?<?= e(http_build_query(['status'=>$status,'receipt'=>$receipt,'search'=>$search,'page'=>$page-1])) ?>">Previous</a><?php endif; ?><span>Page <?= e((string)$page) ?> of <?= e((string)$pages) ?></span><?php if ($page<$pages): ?><a class="btn btn-quiet" href="?<?= e(http_build_query(['status'=>$status,'receipt'=>$receipt,'search'=>$search,'page'=>$page+1])) ?>">Next</a><?php endif; ?></nav><?php endif; ?>
</section></div></main><?php require __DIR__.'/../includes/footer.php'; ?></body></html>
